// Determine which automation to run based on trigger time
const now = new Date();
const hour = now.getHours();
const dayOfWeek = now.getDay();
const dayOfMonth = now.getDate();

let automationType;
if (dayOfMonth === 1 && hour === 0) {
  automationType = 'monthly_reset';
} else if (dayOfWeek === 1 && hour === 10) {
  automationType = 'weekly_report';
} else if (hour >= 17) {
  automationType = 'evening_check';
} else {
  automationType = 'morning_check';
}

return {
  automation_type: automationType,
  trigger_time: now.toISOString(),
  date_today: now.toISOString().split('T')[0]
};

// Template morning message (no AI required)
const data = $json;
const checkins = data.checkins_today || 0;
const checkouts = data.checkouts_today || 0;
const tickets = data.open_tickets || 0;

let message = `☀️ Good morning, ${data.owner_name || 'Owner'}!\n\n`;
message += `📊 *${data.property_name || 'Your Property'}* Daily Summary:\n`;
message += `• Check-ins today: ${checkins}\n`;
message += `• Check-outs today: ${checkouts}\n`;

if (tickets > 0) {
  message += `• Open tickets: ${tickets}\n\n`;
  message += `⚠️ You have open maintenance tickets to address.`;
} else if (checkins > 0 || checkouts > 0) {
  message += `\nHave a productive day! 💪`;
} else {
  message += `\nQuiet day ahead. Enjoy! ☕`;
}

return {
  channel: data.preferred_platform || 'telegram',
  recipient: data.owner_contact,
  message: message,
  property_id: data.property_id,
  customer_id: data.customer_id
};

// Template evening message
const data = $json;

let message = `🌙 Evening Check-in Update\n\n`;
message += `🏠 *${data.property_name || 'Property'}*\n`;

if (data.guest_name && data.guest_name !== 'Guest' && data.booking_id) {
  message += `👤 Guest: ${data.guest_name}\n`;
  message += `📅 Check-in today\n\n`;
  message += `✅ Please verify the property is ready for arrival!`;
} else {
  message += `\nNo check-ins scheduled for today.\n`;
  message += `Have a relaxing evening! 🌟`;
}

return {
  channel: data.preferred_platform || 'telegram',
  recipient: data.owner_contact,
  message: message,
  property_id: data.property_id,
  customer_id: data.customer_id
};

// Template weekly report
const data = $json;
const revenue = parseFloat(data.total_revenue) || 0;
const bookings = parseInt(data.total_bookings) || 0;
const newBookings = parseInt(data.new_bookings_week) || 0;

let message = `📊 *Weekly Performance Report*\n\n`;
message += `🏠 *${data.property_name || 'Property'}*\n\n`;
message += `*30-Day Metrics:*\n`;
message += `• Total Bookings: ${bookings}\n`;
message += `• Revenue: $${revenue.toFixed(2)}\n`;
message += `• New This Week: ${newBookings}\n\n`;

if (bookings > 0) {
  message += `Keep up the great work! 🎉`;
} else {
  message += `Consider promotional activities to boost bookings.`;
}

return {
  channel: data.preferred_platform || 'telegram',
  recipient: data.owner_contact,
  message: message,
  property_id: data.property_id,
  customer_id: data.customer_id
};

