// Prepare monthly reset notification
const now = new Date();
const currentMonth = now.toLocaleString('default', { month: 'long', year: 'numeric' });

const message = `🗓️ *Monthly Budget Reset*\n\n` +
  `Your API budget for *${currentMonth}* has been reset.\n\n` +
  `💳 *New Month Budget:*\n` +
  `💰 Available: $30.00\n\n` +
  `Your AI assistant is ready for another month of service! 🤖`;

return {
  message: message,
  month: currentMonth,
  success: true
};

// Log execution result
return {
  success: true,
  automation_type: $('Determine Automation').item.json.automation_type,
  executed_at: new Date().toISOString(),
  message_sent: !!$json.recipient
};
